visible.script:
let layer, seq=0, updates=0;
function state(){const frametime=engine.frametime;return {runtime:engine.runtime,frametimeType:typeof frametime,
    frametime:typeof frametime==='number'?frametime:null,frame:layer.getFrame(),rate:layer.rate,playing:layer.isPlaying()};}
function log(label,value){if(seq>=24)return;const row=JSON.stringify({probe:'clock-step',version:1,cell:1,seq:++seq,kind:'diagnostic',label,fields:[value]});if(row.length<900)console.log('SKWD_A02:'+row);}
function call(fn){try{return {returnType:typeof fn(),state:state()}}catch(error){return {error:{name:String(error?.name),message:String(error?.message)},state:state()}}}
export function init(){
    layer=thisLayer.getAnimationLayer('Animación 1');
    log('init',{state:state(),fps:layer.fps,frameCount:layer.frameCount,duration:layer.duration});
    log('rate-two',call(()=>{layer.rate=2}));
    log('seek-zero',call(()=>layer.setFrame(0)));
    log('play',call(()=>layer.play()));
    return true;
}
export function update(){
    if(updates>=9)return true;
    updates++;
    log('update-'+updates,state());
    if(updates===3)log('rate-one',call(()=>{layer.rate=1}));
    if(updates===5)log('pause',call(()=>layer.pause()));
    if(updates===6)log('resume',call(()=>layer.play()));
    if(updates===8){log('final-pause',call(()=>layer.pause()));log('seek-held-120',call(()=>layer.setFrame(120)));}
    return true;
}
